  `tier` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'minor',
  `color` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#c9a227',
  `sort_order` int unsigned NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `stock` int unsigned DEFAULT NULL,
  `stock_depleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
